def rle(s):
    if not s:
        return ''
    result = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1
    result.append(f"{current_char}{count}")
    return ''.join(result)

def to_base(n, b):
    """
    Convert a non-negative integer n to a string representation in base b (2 <= b <= 16).
    Digits are represented by lowercase letters a-f for values 10-15.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if not (2 <= b <= 16):
        raise ValueError("b must be between 2 and 16 inclusive")
    if n == 0:
        return "0"
    digits = "0123456789abcdef"
    result = []
    while n > 0:
        n, rem = divmod(n, b)
        result.append(digits[rem])
    return ''.join(reversed(result))
